{
  "incident": {
    "component": "kubernetes",
    "category": "disk_pressure",
    "status": "firing",
    "summary": "PVC data-loki-0 in namespace logging is 92% full with an estimated 16 hours until exhaustion."
  },
  "assessment": {
    "urgency": "medium",
    "rationale": "The volume is 92% full with a linear time-to-exhaustion (TTE) of 16.0 hours, which is below the 72h threshold for high urgency but requires attention within the current shift."
  },
  "facts": [
    "PVC name: data-loki-0",
    "Namespace: logging",
    "Used percentage: 92.0%",
    "Filesystem size: 107.37 GB",
    "Available bytes: 8.59 GB",
    "Growth rate: 536.87 MB/hour",
    "Estimated time to exhaustion: 16.0 hours",
    "StorageClass: local-path",
    "allow_volume_expansion: False",
    "reclaim_policy: Delete"
  ],
  "missing_context": [
    {
      "item": "user_impact",
      "why": "To determine if this is a 'fire' requiring immediate mitigation or a routine capacity issue (global.impact.001).",
      "how_to_check": "Check Loki error rates, query latency, and check if any logging-dependent services are failing."
    },
    {
      "item": "recent_changes",
      "why": "To see if a recent deployment or config change caused the increased growth rate (global.context.001).",
      "how_to_check": "Check kubectl rollout history in the logging namespace and CI/CD deployment logs."
    }
  ],
  "immediate_actions": [
    {
      "action": "Identify the top growing directories inside the pod",
      "purpose": "To find the source of growth without risking data corruption (k8s.storage.004).",
      "conditions": "Pod data-loki-0 must be running.",
      "expected_effect": "Pinpoint whether logs, indices, or other data are consuming space.",
      "risks": "Minimal; read-only operation.",
      "requires_approval": false,
      "verify": "Check output of du command.",
      "rule_ids": [
        "k8s.storage.004"
      ]
    },
    {
      "action": "Check for recent configuration changes to Loki retention",
      "purpose": "To see if retention policies were accidentally relaxed (global.context.001).",
      "conditions": "Access to Helm/ConfigMap/ArgoCD history.",
      "expected_effect": "Identify if the growth is an expected result of a change.",
      "risks": "None.",
      "requires_approval": false,
      "verify": "Review config history.",
      "rule_ids": [
        "global.context.001"
      ]
    }
  ],
  "investigation_steps": [
    {
      "step": "Inspect pod filesystem usage",
      "hypothesis": "A specific directory (e.g., chunks or index) is growing unexpectedly.",
      "how_to_check": "kubectl exec -it data-loki-0 -n logging -- du -xh --max-depth=2 /data | sort -h | tail"
    },
    {
      "step": "Analyze growth trend via PromQL",
      "hypothesis": "The growth is a steady linear increase rather than a sudden spike.",
      "how_to_check": "predict_linear(kubelet_volume_stats_available_bytes{persistentvolumeclaim='data-loki-0'}[6h], 4*3600)"
    }
  ],
  "root_cause_hypotheses": [
    "Loki retention policy is too long or misconfigured.",
    "Sudden increase in log volume from a specific application.",
    "Loki index or chunk files are not being cleaned up as expected."
  ],
  "dangerous_operations": [
    {
      "operation": "Manual deletion of files inside the Loki data directory",
      "why_dangerous": "Deleting files in database/broker data directories can corrupt the service (linux.storage.006).",
      "rule_id": "linux.storage.006"
    },
    {
      "operation": "Deleting the PVC to recreate it larger",
      "why_dangerous": "The reclaim policy is 'Delete', so deleting the PVC will destroy all existing Loki data (k8s.storage.003).",
      "rule_id": "k8s.storage.003"
    },
    {
      "operation": "Attempting to resize the volume",
      "why_dangerous": "The StorageClass 'local-path' has allowVolumeExpansion set to False; manual intervention might fail or cause instability (k8s.storage.001).",
      "rule_id": "k8s.storage.001"
    }
  ],
  "applied_expert_rules": [
    "global.impact.001",
    "global.context.001",
    "global.safety.001",
    "global.triage.001",
    "k8s.storage.001",
    "k8s.storage.003",
    "k8s.storage.004",
    "linux.storage.006"
  ],
  "incident_update": "⚠️ *Alert: PVC data-loki-0 is 92% full (namespace: logging).* Estimated 16h until exhaustion. Investigating growth source via `du` and checking recent config changes. Note: `allowVolumeExpansion` is False for this StorageClass. Will verify impact on Loki query availability next."
}
